import{TASKS07,EXERCISES07,assess07,checkExercise07,RUN07_T12,RUN07_T2,COMPARISON07,anneal}from'./anneal07.mjs';import{board}from'../lessons/02/teaching/visuals.mjs';
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const rowsOf=pack=>Object.entries(pack||{}).map(([id,r])=>[id,r.x,r.y,r.w,r.h]).sort((a,b)=>a[0]<b[0]?-1:1);
export function lab07Page({code,task,quizBlock=''}){return`<main id="main" class="wrap focused-lesson"><header class="focused-hero"><div class="breadcrumbs"><a href="../../index.html">课程</a> / Lab 07</div><h1>偶尔后退，能否走得更远？</h1><p class="lead">读一条可复现的搜索轨迹，审计状态机，再做一次等预算比较。</p><nav class="focused-nav" aria-label="本课学习路径"><a href="#video">01 互动教学</a><a href="#lab">02 综合 Lab · Python</a><a href="#quiz">03 课后习题</a></nav></header>
<section id="video" class="focused-section"><span id="film"></span><span class="eyebrow">01 / LEARN</span><h2>互动讲解</h2><p class="small">先看一遍；轨迹、日志与比较表会按推理切换。</p><iframe id="interactive-teaching-frame" title="Lab7互动教学" src="teaching/?embed=1&v=anneal-1" allow="autoplay; fullscreen" scrolling="no" style="width:100%;height:850px;border:0;display:block"></iframe></section>
<section id="lab" class="focused-section"><span class="eyebrow">02 / TRACE · AUDIT · COMPARE</span><h2>轨迹审计台</h2><p>三项任务：审计默认轨迹、修复"拒绝后当前被修改"的状态机、完成等预算多种子比较。</p><label>选择任务 <select id="lab07-task">${TASKS07.map(t=>`<option value="${t.id}">${esc(t.title)}</option>`).join('')}</select></label><p id="lab07-prompt"></p><button id="lab07-reset">重置当前任务</button>
<div class="lab04-console"><label>种子 <input id="lab07-seed" type="number" value="7" min="0" max="99999" style="width:90px"></label><label>温度 <input id="lab07-T" type="number" value="12" min="0.1" max="100" step="0.1" style="width:90px"></label><label>步数 <input id="lab07-steps" type="number" value="120" min="1" max="500" style="width:90px"></label><button id="lab07-run" class="primary">生成搜索轨迹</button><p id="lab07-parse" role="status"></p></div>
<div id="lab07-board" class="lab02-board"></div><div class="lab04-side"><div id="lab07-stepinfo"></div><div id="lab07-summary"></div></div><div id="lab07-controls"><label>查看第 <select id="lab07-step"></select> 步</label><button id="lab07-compare">等预算比较：种子{3,7,11}×T{12,2}×120步（一次性）</button></div><p id="lab07-compare-result" role="status"></p>
<div id="lab07-evidence"></div><label>写下你的推理（判定依据来自日志的哪一列）<textarea id="lab07-explanation" rows="3" style="display:block;width:100%"></textarea></label><button id="lab07-check" class="primary">检查并保存</button> <button id="lab07-hint">需要一点提示</button><p id="lab07-result" role="status" style="white-space:pre-line"></p>
<article id="python" class="python-integrated"><h3>Python Lab：实现通用退火状态机 anneal</h3><p>${esc(task.prompt.zh)}</p><details><summary>接口合同与状态机规则</summary><p>已提供：Lab6 解码器（经 make_decoder 适配）、make_score(outline)=盒面积+100×越界、make_feasible(outline,catalog)、make_neighbor(rng)=交换一个排列里的两个名字、constant_rng(values) 与 cooling(t0,rate)。rng 的合同：每次调用返回 [0,1) 的均匀随机数。</p><p>状态机规则：当前/候选/最好合法解分开保存；ΔE≤0 直接接受；ΔE>0 时 u&lt;exp(−ΔE/T) 才接受；拒绝的候选不得修改当前解；最好合法解只在可行且更优时更新；恰好评估 budget 次；日志每步记录 T、候选能量、ΔE、u、accepted、current_energy、best_energy。返回 {'best_legal','best_energy','final','final_energy','log','accepted','evals'}。</p><p>${task.tests.length}项检查是基线。再写一个自己的测试并说明它能排除哪种错误实现（例如"拒绝后修改当前"或"把历史最好当作当前"）。</p></details><textarea id="python-source" class="python-editor" aria-label="Python source code" spellcheck="false">${esc(code)}</textarea><div class="python-toolbar"><button id="python-run" class="primary">运行综合检查</button><button id="python-stop" disabled>停止</button><button id="python-reset">恢复模板</button></div><pre id="python-output" class="python-output" role="status">尚未检查。修改代码后，需要重新运行。</pre></article></section>
<section id="quiz" class="focused-section"><span class="eyebrow">03 / TRANSFER · COUNTEREXAMPLE · BOUNDARY</span><h2>课后练习：把结论的边界说清楚</h2><p>除了数值，也写出推理。做完后可以对照参考要点检查。</p>${EXERCISES07.map(q=>`<article class="extended-exercise" data-exercise07="${q.id}"><h3>${esc(q.title)}</h3><p>${esc(q.prompt)}</p><div class="exercise-fields">${q.fields.map(([key,label])=>`<label>${esc(label)} <input type="number" step="any" data-field="${key}"></label>`).join('')}</div><label>你的推理<textarea data-explain rows="3"></textarea></label><button data-check>检查并保存</button> <button data-reveal>查看参考要点</button><p data-result role="status"></p><p data-rubric hidden>${esc(q.rubric)}</p></article>`).join('')}${quizBlock}</section></main>`;}
export function bindLab07({progress,save}){const $=s=>document.querySelector(s);let task=TASKS07[0],result=null,run=null,step=1,edited=false,hint=false;
 progress.lab07Submissions=progress.lab07Submissions||{};progress.exercises07=progress.exercises07||{};
 function render(){$('#lab07-prompt').textContent=task.prompt;$('#lab07-seed').value=task.seed;$('#lab07-T').value=task.T;$('#lab07-steps').value=task.steps;
  $('#lab07-parse').textContent=run?`轨迹完成：${run.events.length} 步，接受 ${run.events.filter(e=>e.accepted).length} 次，最好合法面积 ${run.events.at(-1).bestEnergy??'—'}，最终能量 ${run.events.at(-1).energy}`:'点击"生成搜索轨迹"开始（固定种子，可逐步重放）。';
  const rows=run?run.events[Math.min(step,run.events.length)-1].pack:null;
  $('#lab07-board').innerHTML=rows?`<svg viewBox="0 0 960 540" role="group" aria-label="当前解布局"><defs><pattern id="collision" width="8" height="8" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><rect width="8" height="8" fill="#efc2ad"/><path d="M0 0V8" stroke="#a74330" stroke-width="3"/></pattern></defs>${board(rowsOf(rows),task.outline,{x:70,y:60,w:810,h:415})}</svg>`:'<p style="padding:40px">尚未生成轨迹。</p>';
  if(run){const e=run.events[Math.min(step,run.events.length)-1];
   $('#lab07-stepinfo').innerHTML=`<h3>第 ${Math.min(step,run.events.length)} 步日志</h3><table style="width:100%"><tbody>${[['T',e.T.toFixed(3)],['候选能量',e.candidateEnergy],['ΔE',e.delta],['u',e.u.toFixed(4)],['p',e.probability.toFixed(4)],['判定',e.accepted?'接受':'拒绝'],['之后当前能量',e.energy],['之后最好合法',e.bestEnergy??'—']].map(([k,v])=>`<tr><td>${esc(k)}</td><td>${esc(String(v))}</td></tr>`).join('')}</tbody></table>`;
   $('#lab07-summary').innerHTML=`<h3>当前编码</h3><p>pos=${esc(e.pos.join(''))}<br>neg=${esc(e.neg.join(''))}</p>`;}
  else{$('#lab07-stepinfo').innerHTML='<h3>日志</h3><p>生成轨迹后显示。</p>';$('#lab07-summary').innerHTML='';}
  const sel=$('#lab07-step');if(run){sel.innerHTML=run.events.map((e,i)=>`<option value="${i+1}" ${i+1===step?'selected':''}>第 ${i+1} 步（${e.accepted?'接受':'拒绝'}，ΔE=${e.delta}）</option>`).join('');sel.disabled=false;}else{sel.innerHTML='';sel.disabled=true;}
  $('#lab07-evidence').innerHTML=`<div class="exercise-fields">${task.fields.map(([key,label])=>`<label>${esc(label)} <input id="lab07-${key}" type="number" step="any"></label>`).join('')}</div>`;}
 $('#lab07-task').onchange=e=>load(e.target.value);$('#lab07-reset').onclick=()=>load(task.id);
 $('#lab07-run').onclick=()=>{const seed=Number($('#lab07-seed').value),T=Number($('#lab07-T').value),steps=Number($('#lab07-steps').value);
  if(!Number.isInteger(seed)||seed<0||seed>99999||!Number.isInteger(steps)||steps<1||steps>500||!Number.isFinite(T)||T<=0||T>100){$('#lab07-parse').textContent='参数无效：种子0–99999、步数1–500、0<T≤100。';return;}
  task={...task,seed,T,steps};run=anneal({seed,steps,temperature:T});step=1;edited=true;render();};
 $('#lab07-step').onchange=e=>{step=Number(e.target.value);render();};
 $('#lab07-compare').onclick=()=>{if($('#lab07-compare-result').textContent)return;$('#lab07-compare-result').textContent=`T=12：种子3/7/11 最好合法面积 = ${RUN07_T12.seed3.events.at(-1).bestEnergy} / ${RUN07_T12.seed7.events.at(-1).bestEnergy} / ${RUN07_T12.seed11.events.at(-1).bestEnergy}（和 ${COMPARISON07.sumT12}）；T=2：${RUN07_T2.seed3.events.at(-1).bestEnergy} / ${RUN07_T2.seed7.events.at(-1).bestEnergy} / ${RUN07_T2.seed11.events.at(-1).bestEnergy}（和 ${COMPARISON07.sumT2}）。结论只属于这组数据与参数。`;};
 $('#lab07-hint').onclick=()=>{hint=true;progress.lab07Submissions[task.id]={...(progress.lab07Submissions[task.id]||{}),hintUsed:true};save();$('#lab07-result').textContent=task.hint;};
 $('#lab07-check').onclick=()=>{const e={};for(const key of['accStep','accDelta','rejStep','rejDelta','curAfter2','curAfter6','sumT12','sumT2'])e[key]=$('#lab07-'+key)?.value;const res=assess07(task.id,e,edited);
  const explanation=$('#lab07-explanation').value;
  progress.lab07Submissions[task.id]={version:1,seed:task.seed,T:task.T,steps:task.steps,evidence:e,numericPassed:res.ok,explanation,hintUsed:hint,explanationStatus:'submitted-not-graded'};save();
  $('#lab07-result').textContent=res.errors.length?res.errors.join('\n'):explanation.trim().length<30?'数值通过，请再写清楚判定依据来自日志的哪一列。':'数值通过，解释已保存。请确认结论有日志与多种子支撑。';};
 function load(id){task=TASKS07.find(t=>t.id===id);result=null;run=null;step=1;edited=false;hint=!!progress.lab07Submissions[task.id]?.hintUsed;$('#lab07-result').textContent='';$('#lab07-compare-result').textContent='';$('#lab07-explanation').value='';render();}
 for(const article of document.querySelectorAll('[data-exercise07]')){const id=article.dataset.exercise07,saved=progress.exercises07[id]||{};for(const input of article.querySelectorAll('[data-field]'))input.value=saved.values?.[input.dataset.field]??'';article.querySelector('[data-explain]').value=saved.explanation||'';let revealed=!!saved.revealed;
  article.querySelector('[data-check]').onclick=()=>{const values=Object.fromEntries([...article.querySelectorAll('[data-field]')].map(e=>[e.dataset.field,e.value])),explanation=article.querySelector('[data-explain]').value,ok=checkExercise07(id,values);progress.exercises07[id]={values,explanation,numericPassed:ok,revealed,explanationStatus:'submitted-not-graded'};save();article.querySelector('[data-result]').textContent=!ok?'数值还不对，请核对能量公式、接受概率或多种子结果。':explanation.trim().length<30?'数值通过，请补上你的推理。':'数值通过，解释已保存。请按参考要点检查依据。'+(revealed?'（已查看参考）':'');};
  article.querySelector('[data-reveal]').onclick=()=>{revealed=true;article.querySelector('[data-rubric]').hidden=false;progress.exercises07[id]={...(progress.exercises07[id]||{}),revealed:true};save();article.querySelector('[data-result]').textContent='参考要点已显示，不计作独立完成的证明。';};}
 load(TASKS07[0].id);
}

